var pos := [{"x": 22.0 * 40.0, "y": 30.0 * 40.0}]
var r = NetworkIntegration.route_action({"type": "PLACE_REINFORCEMENT", "player": 1, "unit_id": "U_DROP_POD_A", "model_positions": pos, "placement_type": "deep_strike"})
print("[sm11e-m4a] drop pod placement: ", r.get("success", false), " ", r.get("error", r.get("errors", "")))
tree.current_scene._recreate_unit_visuals()
return r.get("success", false)

var ph = PhaseManager.get_current_phase_instance()
var pod = GameState.get_unit("U_DROP_POD_A").models[0].position
var c := Vector2(float(pod.x), float(pod.y)) / 40.0
var n: int = GameState.get_unit("U_INTERCESSOR_SQUAD_A").models.size()
var pos := []
for i in range(n):
	var a := PI + PI * float(i) / float(maxi(1, n - 1))
	var p := c + Vector2(cos(a), sin(a)) * 2.3
	pos.append([p.x * 40.0, p.y * 40.0])
var boyz = GameState.get_unit("U_BOYZ_B")
var saved := []
for i in range(boyz.models.size()):
	saved.append(boyz.models[i].position)
	boyz.models[i].position = {"x": (c.x - 6.0 + (i % 10) * 1.3) * 40.0, "y": (c.y - 9.0 - (i / 10) * 1.3) * 40.0}
var v: Dictionary = ph._validate_confirm_disembark({"type": "CONFIRM_DISEMBARK", "actor_unit_id": "U_INTERCESSOR_SQUAD_A", "player": 1, "payload": {"positions": pos}})
for i in range(boyz.models.size()):
	boyz.models[i].position = saved[i]
var v2: Dictionary = ph._validate_confirm_disembark({"type": "CONFIRM_DISEMBARK", "actor_unit_id": "U_INTERCESSOR_SQUAD_A", "player": 1, "payload": {"positions": pos}})
print("[sm11e-m4a] drop pod near-enemy disembark: ", v, " | Boyz back far away: ", v2)
return str(v.get("errors", [])).contains("more than 8") and bool(v2.get("valid", false))

DebugLogger._flush_buffer()
var f = FileAccess.open(DebugLogger.get_real_log_file_path(), FileAccess.READ)
var n := 0
while f != null and not f.eof_reached():
	var l := f.get_line()
	if l.contains("[ERROR"):
		n += 1
		print("[sm11e-m4a] debug-log ERROR: ", l)
return n
